print(f"scipy version: {scipy.__version__}")
print(f"pandas version: {pd.__version__}")
print(f"cirq version: {cirq.__version__}")
print(f"cirq_ionq version: {ionq.__version__}")

# 1. Initialize the service with your API key
# Replace 'YOUR_API_KEY_HERE' with your actual IonQ API key
service = ionq.Service(api_key='YOUR_API_KEY_HERE')

# 2. Define your quantum circuit (e.g., a simple Bell State)
q0, q1 = cirq.LineQubit.range(2)
circuit = cirq.Circuit(
    cirq.H(q0),
    cirq.CNOT(q0, q1),
    cirq.measure(q0, q1, key='result')
)

# 3. Submit to the QPU (Targeting simulator for initial verification)
job = service.create_job(
    circuit=circuit,
    repetitions=1000,
    target='simulator'
)

print(f"Job submitted! ID: {job.id()}")

# 4. Retrieve results
result = job.results()
print("Measurement Histogram:", result.histogram(key='result'))

