import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit_ionq import IonQProvider
import matplotlib.pyplot as plt

# ==============================================================================
# STEP 2: CREDENTIAL AUTHENTICATION
# ==============================================================================
# Replace with your actual IonQ API key from your cloud console dashboard
IONQ_API_KEY = "YOUR_IONQ_API_KEY_HERE"
provider = IonQProvider(IONQ_API_KEY)

# Select your backend:
# For free rapid testing, use: 'ionq_simulator'
# For real trapped-ion hardware deployment, use: 'ionq_qpu'
backend = provider.get_backend('ionq_simulator')

print(f"Successfully locked onto Backend: {backend.name}\n")

# ==============================================================================
# STEP 3: THE ANTI-ENTROPY QUANTUM BIOLOGY CIRCUIT
# ==============================================================================
# Qubit 0: Head Hair Gene (SIRT1 Reset Track)
# Qubit 1: Tumor Suppressor Guard (p53 Safety Lock)
qc = QuantumCircuit(2, 2)

# Apply a Hadamard gate to Qubit 0 to put the aging track into a 50/50 superposition
qc.h(0)

# Entangle Qubit 0 with Qubit 1 using a Controlled-NOT gate.
# This ensures the hair growth track ONLY activates if the safety guard flips active!
qc.cx(0, 1)

# Map the quantum states to the classical output channels
qc.measure([0, 1], [0, 1])

print("--- Quantum Circuit Manifest Architecture ---")
print(qc.draw(output='text'))

# ==============================================================================
# STEP 4: TRANSPILATION & CLOUD RUN EXECUTION
# ==============================================================================
print("\nTranspiling circuit parameters for IonQ's native gate system...")
transpiled_circuit = transpile(qc, backend)

print("Transmitting quantum payload to IonQ Cloud Server...")
# Run the circuit for 1000 sampling "shots"
job = backend.run(transpiled_circuit, shots=1000)

# ==============================================================================
# STEP 5: HARVEST RESULTS & GRAPH PHASES
# ==============================================================================
print("Awaiting cloud response...")
result = job.result()
counts = result.get_counts()

print("\n======================= METRICS HARVESTED =======================")
print(f"Final State Distribution Counts: {counts}")
print("=================================================================")

# Plot histogram of the ground-state probabilities
from qiskit.visualization import plot_histogram
plot_histogram(counts)
plt.show()

