# Select your backend.
# TIP: Test on 'ionq_simulator' first to save credits, then swap to 'ionq_qpu' for real hardware.
backend = provider.get_backend("ionq_simulator")

# =====================================================================
# 3. DEFINE THE FRIEDMANN COSMOLOGY EXPANSION CIRCUIT
# =====================================================================
# 2-qubit system representing the quantum scale factor a(t)
qc = QuantumCircuit(2)

# Step A: Tunneling Operator (Hadamard creates cosmic superposition)
qc.h(0)

# Step B: Gravitational/Kinetic Coupling (CNOT entangles the geometry)
qc.cx(0, 1)

# Step C: Dynamic Expansion Push (Phase shift via Cosmological Constant)
cosmic_time_step = np.pi / 4
qc.rz(cosmic_time_step, 1)

qc.measure_all()

