import random
from qiskit import QuantumCircuit
from qiskit_ionq import IonQProvider

# 2. PROVIDE YOUR API KEY
# Replace the text below with your actual IonQ Cloud API Key
IONQ_API_KEY = "YOUR_IONQ_API_KEY_HERE"
provider = IonQProvider(token=IONQ_API_KEY)

# 3. CHOOSE YOUR BACKEND (Simulator first, swap to 'ionq_qpu' for real hardware)
# Available backends: provider.get_backend('ionq_simulator') OR provider.get_backend('ionq_qpu')
backend = provider.get_backend('ionq_simulator')

# 4. BUILD THE PROTOCOL (Using the same logic as your BB84 Photon project)
qc = QuantumCircuit(1, 1)
alice_bit = random.randint(0, 1)
alice_basis = random.randint(0, 1)  # 0=Rect, 1=Diag
bob_basis = random.randint(0, 1)

if alice_bit == 1: qc.x(0)
if alice_basis == 1: qc.h(0)
if bob_basis == 1: qc.h(0)
qc.measure(0, 0)

# 5. RUN THE CIRCUIT
print(f"Submitting job to {backend.name}...")
job = backend.run(qc, shots=1)

# 6. GET THE RESULT
result = job.result()
counts = result.get_counts()
print("\nExecution complete!")
print("Result counts:", counts)

