# --- Setup and Imports ---
import pennylane as qml
from pennylane import numpy as np
from pennylane_ionq import ops
import os
from google.colab import userdata

# --- 1. API Key Authentication ---
# Securely fetch the API key from Colab's built-in Secrets manager.
# Ensure you have added your key in the Secrets tab (key icon on the left) under the name 'IONQ_API_KEY'.
try:
    os.environ["IONQ_API_KEY"] = userdata.get('IONQ_API_KEY')
    print("API Key loaded successfully.")
except userdata.SecretNotFoundError:
    print("ERROR: 'IONQ_API_KEY' not found in Colab Secrets. Please add it before running.")

# --- 2. Hardware Backend Initialization ---
# Target the actual quantum processing unit (QPU).
# Note: Executing on "ionq.qpu" consumes your hardware credits/shots.
try:
    dev = qml.device("ionq.qpu", wires=4)
    print("IonQ QPU backend initialized.")
except Exception as e:
    print(f"Failed to initialize backend: {e}")

# --- 3. Quantum Circuit Definition ---
@qml.qnode(dev)
def quantum_field_circuit(frequencies):
    """
    Applies standard model vibrational mappings and simulates
    particle interactions using native Trapped-Ion gates.
    """
    # Baseline frequency rotations
    for i in range(4):
        qml.RY(frequencies[i], wires=i)

    # Force/virtual particle simulation using Mølmer-Sørensen (Ising) gates
    ops.XX(frequencies[4], wires=[0, 1])
    ops.YY(frequencies[5], wires=[1, 2])
    ops.ZZ(frequencies[6], wires=[2, 3])
    ops.XX(frequencies[7], wires=[3, 0])

    return qml.probs(wires=[0, 1, 2, 3])

# --- 4. Execution and Output ---
print("Submitting circuit to IonQ hardware queue...")

# Frequencies representing the energy inputs (requires 8 distinct values for this circuit)
input_frequencies = np.array([0.15, 0.45, 0.85, 1.10, 0.25, 0.75, 1.05, 0.90], requires_grad=False)

# Execute the circuit (this step waits for the IonQ server queue)
try:
    results = quantum_field_circuit(input_frequencies)

    print("\n--- Hardware Execution Complete ---")
    print("Significant Probability States (Threshold > 1%):")

    for state_index, probability in enumerate(results):
        if probability > 0.01:
            # Convert to a 4-bit binary string to visualize the space nodes
            binary_state = format(state_index, '04b')
            print(f"Node |{binary_state}⟩: {probability * 100:.2f}%")

except Exception as e:
    print(f"\nExecution Failed. Error details: {e}")

