import pennylane as qml
from pennylane import numpy as np
from google.colab import userdata

# 1. Setup access
ionq_key = userdata.get('IONQ_API_KEY')

# 2. Define the hardware device (IonQ QPU)
# 'ionq.qpu' sends the circuit to actual quantum hardware
dev_ionq = qml.device('ionq.qpu', wires=8, qpu='aria-1', api_key=ionq_key)

@qml.qnode(dev_ionq)
def ionq_gblock_circuit(params):
    # Initialize valence registry
    qml.RX(params[0], wires=0)
    qml.RX(params[0], wires=1)
    for i in range(2, 8):
        qml.RY(params[1], wires=i)

    return [qml.expval(qml.PauliZ(i)) for i in range(8)]

# 3. Execution
params = np.array([2.15, 0.60], requires_grad=False)

print("Sending job to IonQ hardware...")
# Note: Real QPU jobs can take time to queue
results = ionq_gblock_circuit(params)
print(f"Hardware Results: {results}")

