import os
from qiskit import QuantumCircuit, transpile
from qiskit_ionq import IonQProvider

# 1. Initialize the IonQ Provider using your API key
# Get your API key from the IonQ Console (https://cloud.ionq.com)
IONQ_API_KEY = "YOUR_IONQ_API_KEY"
provider = IonQProvider(IONQ_API_KEY)

# 2. Select your target backend
# For actual quantum hardware, use: 'ionq.qpu'
# For the high-fidelity cloud simulator, use: 'ionq.simulator'
backend = provider.get_backend("ionq.simulator")

# 3. Construct your Quantum Circuit (3-Qubit Greenberger-Horne-Zeilinger state)
qc = QuantumCircuit(3, 3)
qc.h(0)          # Place qubit 0 in superposition
qc.cx(0, 1)      # Entangle qubit 0 and 1
qc.cx(1, 2)      # Entangle qubit 1 and 2
qc.measure([0, 1, 2], [0, 1, 2]) # Measure results to classical registers

# 4. Transpile the circuit to optimize it for IonQ's native gate set
transpiled_qc = transpile(qc, backend)

# 5. Submit the job to the IonQ execution queue
print("📡 Submitting quantum job payload to IonQ...")
job = backend.run(transpiled_qc, shots=1024)

# 6. Monitor and retrieve execution results
print(f"🆔 Job ID: {job.job_id()}")
print("⏳ Waiting for IonQ execution loop to finish...")
result = job.result()

# 7. Print output matrix
counts = result.get_counts()
print("\n📊 [SUCCESS] Execution Complete. Telemetry Results:")
print(counts)

