import time
from qiskit import QuantumCircuit
from qiskit.providers.jobstatus import JobStatus
from qiskit_ionq import IonQProvider

# 2. Authenticate with your IonQ API Key
# Replace 'YOUR_IONQ_API_KEY_HERE' with your actual token from cloud.ionq.com
IONQ_API_KEY = "YOUR_IONQ_API_KEY_HERE"
provider = IonQProvider(token=IONQ_API_KEY)

# 3. Select your target backend
# Use 'ionq_simulator' for testing or 'ionq_qpu' for the actual trapped-ion hardware
backend = provider.get_backend("ionq_simulator")

# 4. Build your Quantum Circuit (Example: 2-Qubit Bell State)
qc = QuantumCircuit(2, 2)
qc.h(0)
qc.cx(0, 1)
qc.measure([0, 1], [0, 1])

print("--- Circuit Layout ---")
print(qc)

# 5. Submit the job
# 'shots' defines execution count. 'debiasing' optimizes error mitigation on the QPU.
print("\nSubmitting circuit execution job to IonQ...")
job = backend.run(qc, shots=1000, debiasing=True)
print(f"Job successfully submitted! Job ID: {job.job_id()}")

# 6. Monitor active job status in real-time
print("Waiting for results from the queue...")
while job.status() not in (JobStatus.DONE, JobStatus.CANCELLED, JobStatus.ERROR):
    print(f"Current Status: {job.status().name} | Checking again in 30 seconds...")
    time.sleep(30)

# 7. Extract and display final results
if job.status() == JobStatus.DONE:
    result = job.result()
    counts = result.get_counts()
    print("\n--- Execution Successful ---")
    print(f"Measurement Counts: {counts}")
else:
    print(f"\nJob failed or was cancelled with status: {job.status().name}")

