import os
from qiskit_ionq import IonQProvider

# 1. Initialize the IonQ provider with your API key
# Tip: It's best practice to store this in Colab Secrets (the key icon on the left)
# and read it via: from google.colab import userdata; API_KEY = userdata.get('IONQ_API_KEY')
IONQ_API_KEY = "your_actual_api_key_here"
provider = IonQProvider(token=IONQ_API_KEY)

# 2. Select your target backend (e.g., "simulator", "ionq_qpu.forte-1", "ionq_qpu.aria-1")
# To see all available backends: print(provider.backends())
backend = provider.get_backend("simulator")

# 3. Submit your quantum circuit (assuming 'qc' is your compiled QuantumCircuit object)
# Set your desired shots, debiasing flags, or error mitigation strategies
print(f"Submitting job to {backend.name}...")
job = backend.run(
    qc,
    shots=1000,
    debiasing=True,             # Recommended for error suppression on QPUs
    symmetry_verification=True,  # Discards measurements violating circuit symmetry
    memory=True                 # Returns individual per-shot bitstrings
)

# 4. Monitor and retrieve the final results (Blocks execution until done)
print(f"Job submitted successfully. Job ID: {job.job_id()}")
print("Waiting for final execution state...")
job.wait_for_final_state()

# 5. Extract and display counts/memory
results = job.result()
counts = results.get_counts()
print("\n--- Execution Finished ---")
print("Measurement Counts:", counts)

if job.get_memory():
    print("First 10 per-shot bitstrings:", job.get_memory()[:10])

