import time
from qiskit import QuantumCircuit
from qiskit_ionq import IonQProvider

# 2. Authenticate and initialize the provider
# Safely input your API key here
IONQ_API_KEY = "YOUR_IONQ_API_KEY"
provider = IonQProvider(token=IONQ_API_KEY)

# 3. Select your target backend
# Use "ionq_simulator" for testing, or a QPU backend like "ionq_qpu.forte-1" for real hardware jobs
backend = provider.get_backend("ionq_simulator")

# 4. Construct your target Quantum Circuit (Example: 2-Qubit Bell State)
qc = QuantumCircuit(2)
qc.h(0)
qc.cx(0, 1)
qc.measure_all()

# 5. Submit the experiment to IonQ's servers
print(f"🚀 Submitting experiment to {backend.name}...")
job = backend.run(qc, shots=1000)

# 6. Monitor execution progress and wait for completion
print(f"Job ID: {job.job_id()}")
while True:
    status = job.status()
    print(f"Checking tracking pipeline... Current Status: {status.name}")

    if status.name in ['DONE', 'CANCELLED', 'ERROR']:
        break
    time.sleep(10)  # Polling interval to protect API query limits

# 7. Extract and display final execution results
if job.status().name == 'DONE':
    result = job.result()
    counts = result.get_counts()
    print("\n✅ Run complete! Final output data:")
    print(counts)
else:
    print(f"\n❌ Execution terminated unexpectedly with status: {job.status().name}")

