import os
from qiskit import QuantumCircuit
from qiskit_ionq import IonQProvider

# 1. Initialize the IonQ Provider
# Replace 'YOUR_IONQ_API_KEY' with your actual token from the IonQ cloud dashboard.
IONQ_TOKEN = 'YOUR_IONQ_API_KEY'
provider = IonQProvider(token=IONQ_TOKEN)

# 2. Select the Backend
# For a real quantum server, use: provider.get_backend('ionq_qpu')
# For a classical simulation backend, use: provider.get_backend('ionq_simulator')
backend = provider.get_backend('ionq_simulator')

# 3. Build the Quantum Circuit (Example: 2-Qubit Bell State)
# This creates the maximum entanglement ("no-touch" connection) between two qubits
qc = QuantumCircuit(2, 2)
qc.h(0)          # Apply Hadamard gate to put Qubit 0 in superposition
qc.cx(0, 1)      # Apply CNOT gate to entangle Qubit 0 and Qubit 1
qc.measure([0, 1], [0, 1])  # Map the quantum state to classical bits

# 4. Submit the Job to the Quantum Server
# Set 'shots' to determine how many times the experiment runs
print("Submitting experiment simulation to IonQ quantum servers...")
job = backend.run(qc, shots=1024)

# 5. Monitor and Retrieve Results
job_id = job.job_id()
print(f"Job successfully submitted! Job ID: {job_id}")
print("Waiting for execution logs...")

# This will block and wait until the quantum computer finishes running your shots
result = job.result()
counts = result.get_counts()

print("\n--- Execution Complete ---")
print("Measurement Results (Credits & Shots):", counts)

