import os
from qiskit import QuantumCircuit
from qiskit_ionq import IonQProvider

# ==========================================
# 1. AUTHENTICATION & PROVIDER SETUP
# ==========================================
# Replace 'YOUR_IONQ_API_KEY' with your actual IonQ API key,
# or set it as an environment variable in Colab.
IONQ_API_KEY = "YOUR_IONQ_API_KEY"

provider = IonQProvider(token=IONQ_API_KEY)

# Select target backend:
# Options: 'ionq_simulator' (Free/Default), 'ionq_qpu.aria-1', 'ionq_qpu.forte-1'
backend = provider.get_backend("ionq_simulator")

print(f"Connected to backend: {backend.name()}")

# ==========================================
# 2. DEFINE YOUR QUANTUM CIRCUIT
# ==========================================
# Example: Creating a 2-qubit Bell State (|00> + |11>) / sqrt(2)
qc = QuantumCircuit(2, 2)
qc.h(0)         # Hadamard gate on qubit 0
qc.cx(0, 1)     # CNOT gate with control 0 and target 1
qc.measure([0, 1], [0, 1])  # Measure both qubits into classical bits

print("\n--- Circuit Diagram ---")
print(qc.draw(output="text"))

# ==========================================
# 3. SUBMIT JOB TO IONQ
# ==========================================
# Submit the circuit to run for a set number of shots (e.g., 1024)
shots = 1024
print(f"\nSubmitting job to {backend.name()} with {shots} shots...")

job = backend.run(qc, shots=shots)

# Retrieve the Unique Job ID (useful for tracking/logging on your dashboard)
job_id = job.job_id()
print(f"Job successfully submitted! Job ID: {job_id}")

# ==========================================
# 4. AWAIT & PROCESS RESULTS
# ==========================================
# Wait for the job to complete and retrieve results
result = job.result()
counts = result.get_counts(qc)
probabilities = result.get_probabilities(qc)

print("\n--- Execution Results ---")
print(f"Measurement Counts: {counts}")
print(f"State Probabilities: {probabilities}")

