import pennylane as qml
import os

# 2. Set your IonQ Cloud API Key
# Replace "YOUR_IONQ_API_KEY" with your actual key from the IonQ Cloud Console
os.environ["IONQ_API_KEY"] = "YOUR_IONQ_API_KEY"

# 3. Initialize the IonQ hardware device
# Use "ionq.qpu" with backend="aria-1" for hardware execution
# Change to "ionq.simulator" if you just want to test without using QPU credits
dev = qml.device("ionq.qpu", backend="aria-1", wires=2, shots=100)

# 4. Define the quantum circuit
@qml.qnode(dev)
def entanglement_test():
    # Prepare a Bell state (entanglement between qubit 0 and 1)
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])

    # Return the probability distribution of the measurement outcomes
    return qml.probs(wires=[0, 1])

# 5. Execute the job and print the telemetry
print("Submitting circuit job to IonQ Aria-1...")
probabilities = entanglement_test()

print("\n--- Execution Complete ---")
print(f"Probability |00⟩: {probabilities[0]:.4f}")
print(f"Probability |01⟩: {probabilities[1]:.4f}")
print(f"Probability |10⟩: {probabilities[2]:.4f}")
print(f"Probability |11⟩: {probabilities[3]:.4f}")

