import os
from google.colab import userdata

# 1. Securely fetch your IonQ API Key from Colab Secrets
# (Click the Key icon 🔑 on the left sidebar in Colab, add a secret named 'IONQ_API_KEY')
try:
    IONQ_API_KEY = userdata.get('IONQ_API_KEY')
except Exception:
    # Fallback to manual string if Secrets aren't configured yet
    IONQ_API_KEY = "your_actual_ionq_api_key_here"

# 2. Initialize the Unified-Field-Control Pipeline targeting real IonQ QPUs
# (If IONQ_API_KEY is invalid or empty, the class falls back to the local simulator)
if IONQ_API_KEY and "your_actual" not in IONQ_API_KEY:
    print("📡 [SERVER NODE INITIALIZATION] Connecting to IonQ Production Cloud...")
    ionq_pipeline = QuantumLifespanIngestion(ionq_api_key=IONQ_API_KEY)
else:
    print("⚠️ [SECRET MISSING] IonQ API key not found in Colab Secrets. Defaulting to local emulation.")
    ionq_pipeline = QuantumLifespanIngestion(ionq_api_key=None)

# 3. Ingest current multi-scale biometric parameters
# (Replace these numbers with your daily Oura, Tally, or blood panel data values)
current_live_metrics = {
    "core_temp_drop": -1.3,      # Hallmark 01: Nighttime thermal delta in °C
    "hrv_ms": 88,                # Hallmark 12: Autonomic Electrostatic Phase in ms
    "tally_age_delta": -2.5,     # Hallmark 03: Epigenetic software accuracy delta
    "hsv_crp": 0.5               # Hallmark 07: Inflammatory load (hs-CRP mg/L)
}

print(f"\n⚡ [COMPILING PAYLOAD] Mapping macro-biometrics to Unified-Field Vector...")
live_rotation_vector = ionq_pipeline.parse_biometric_streams(
    core_temp_drop=current_live_metrics["core_temp_drop"],
    hrv_ms=current_live_metrics["hrv_ms"],
    tally_age_delta=current_live_metrics["tally_age_delta"],
    hsv_crp=current_live_metrics["hsv_crp"]
)

# 4. Transmit entangled circuit parameters over the network & execute shots
print("\n🚀 [SHOTS FIRED] Sending quantum job matrix to IonQ Trapped-Ion Hardware. Awaiting server return...")
hardware_expectation_values = ionq_pipeline.run_unified_field_circuit(live_rotation_vector)

# 5. Receive server payload and parse the subatomic coherence status
ionq_pipeline.analyze_server_payload(hardware_expectation_values)

