def quantum_experiment():
    # Example: Creating a maximally entangled Bell State (Superposition + Entanglement)
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])

    # Return the measurement sample probabilities
    return qml.probs(wires=range(num_qubits))

# 5. Execute the job (This submits the experiment directly to IonQ's servers)
