import os
from qiskit import QuantumCircuit, transpile
from qiskit_ionq import IonQProvider
from qiskit.visualization import plot_histogram
import matplotlib.pyplot as plt

# 2. Authenticate with your IonQ API Key
# Replace 'YOUR_IONQ_API_KEY' with your actual key or set it in your environment
IONQ_API_KEY = "YOUR_IONQ_API_KEY"

provider = IonQProvider(token=IONQ_API_KEY)

# 3. Choose your backend:
# - 'ionq_simulator': Free/cheap for testing logic
# - 'ionq_qpu': The actual trapped-ion quantum computer
backend = provider.get_backend("ionq_simulator")

print(f"Connected to backend: {backend.name()}")

# 4. Construct the Circuit (e.g., Entangled Bell State)
# Trapped ions excel at all-to-all connectivity across register indices
qc = QuantumCircuit(2, 2)
qc.h(0)           # Put Qubit 0 into superposition
qc.cx(0, 1)       # Entangle Qubit 0 and Qubit 1
qc.measure([0, 1], [0, 1])

print("\n--- Circuit Diagram ---")
print(qc.draw(output='text'))

# 5. Transpile and Submit Job to IonQ
print("\nSubmitting job to IonQ...")
transpiled_qc = transpile(qc, backend=backend)
job = backend.run(transpiled_qc, shots=1024)

# 6. Wait for completion and fetch results
print(f"Job ID: {job.job_id()}")
print("Waiting for execution...")
result = job.result()
counts = result.get_counts(qc)

# 7. Display Results
print("\n--- Execution Results (Histogram Counts) ---")
print(counts)

plot_histogram(counts)
plt.title(f"IonQ Execution Results ({backend.name()})")
plt.show()

