import pennylane as qml
from pennylane import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

# 1. SETUP: Configuration and Device
# Change 'noise_probability' to 0.01 to see the Stability Zone expand!
noise_probability = 0.05
dev_mixed = qml.device('default.mixed', wires=4)

# 2. THE ENGINE: Noisy Quantum Circuit
@qml.qnode(dev_mixed)
def run_noisy_quantum_audit(p_noise):
    # State Preparation (The 'qc' logic)
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])
    qml.RY(0.3, wires=2)
    qml.RX(0.1, wires=3)

    # Injecting Environmental Noise
    for i in range(4):
        qml.DepolarizingChannel(p_noise, wires=i)

    return qml.density_matrix(wires=[0, 1, 2, 3])

# 3. THE AUDIT: Data Processing
rho_final = run_noisy_quantum_audit(noise_probability)
layers_map = [([0, 1], 'Nucleus'), ([2], 'Electron Cloud'), ([3], 'Vacuum Field')]
audit_results = []

for wires, name in layers_map:
    # Calculate Entropy (S)
    s_val = float(qml.math.vn_entropy(rho_final, indices=wires))
    # Calculate Purity (P)
    rho_sub = qml.math.reduce_dm(rho_final, indices=wires)
    p_val = float(np.real(np.trace(np.matmul(rho_sub, rho_sub))))
    # Calculate Stability (St = P - S)
    st_val = max(0, p_val - s_val)

    audit_results.append({'layer': name, 'purity': p_val, 'entropy': s_val, 'stability': st_val})

df_audit = pd.DataFrame(audit_results)

# 4. THE DASHBOARD: Visualization
fig, axes = plt.subplots(1, 3, figsize=(22, 6))

# Chart A: Line Chart (Gap Analysis)
axes[0].plot(df_audit['layer'], df_audit['purity'], marker='o', label='Total Purity', color='#0984e3', linewidth=2)
axes[0].plot(df_audit['layer'], df_audit['entropy'], marker='x', label='Entropy (Loss)', color='#d63031', linewidth=2)
axes[0].fill_between(df_audit['layer'], df_audit['purity'], df_audit['entropy'], color='#00b894', alpha=0.1, label='Stability Zone')
axes[0].set_title('A: Line Chart (Gap Analysis)')
axes[0].set_ylim(-0.05, 1.1)
axes[0].legend()
axes[0].grid(True, alpha=0.2)

# Chart B: Standard Bar (Layer Strength)
axes[1].bar(df_audit['layer'], df_audit['purity'], color='#dfe6e9', label='Purity Capacity')
axes[1].bar(df_audit['layer'], df_audit['stability'], color='#00b894', label='Net Stability')
axes[1].set_title('B: Standard Bar (Layer Strength)')
axes[1].legend()

# Chart C: Stacked Bar (The Zero-Sum Audit)
axes[2].bar(df_audit['layer'], df_audit['stability'], label='Stability (Coherence)', color='#00b894')
axes[2].bar(df_audit['layer'], df_audit['entropy'], bottom=df_audit['stability'], label='Entropy (Noise)', color='#d63031')
axes[2].set_title('C: Stacked Bar (Compositional Audit)')
axes[2].set_ylabel('Total Purity (1.0)')
axes[2].set_ylim(0, 1.1)
axes[2].legend()

plt.tight_layout()
plt.show()

