import matplotlib.pyplot as plt
import pandas as pd
import numpy as np
import pennylane as qml

# 1. Regenerate simulation data to ensure audit_data is defined
dev_audit = qml.device('default.qubit', wires=4)

@qml.qnode(dev_audit)
def get_audit_state():
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])
    qml.RY(0.3, wires=2)
    qml.RX(0.1, wires=3)
    return qml.state()

state = get_audit_state()
rho = qml.math.dm_from_state_vector(state)
audit_data = []
layers = [([0, 1], 'Nucleus'), ([2], 'Electron Cloud'), ([3], 'Vacuum Field')]

for wires, name in layers:
    entropy = float(qml.math.vn_entropy(rho, indices=wires))
    rho_sub = qml.math.reduce_dm(rho, indices=wires)
    purity = float(np.real(np.trace(np.matmul(rho_sub, rho_sub))))
    stability = purity - entropy
    audit_data.append({'layer': name, 'purity': purity, 'entropy': entropy, 'stability': stability})

# 2. Prepare DataFrame and Plot
df_audit = pd.DataFrame(audit_data)
fig, axes = plt.subplots(1, 3, figsize=(22, 6))

# --- Option 1: Line Chart (Gap Analysis) ---
axes[0].plot(df_audit['layer'], df_audit['purity'], marker='o', label='Total Purity', color='#0984e3')
axes[0].plot(df_audit['layer'], df_audit['entropy'], marker='x', label='Entropy (Loss)', color='#d63031')
axes[0].fill_between(df_audit['layer'], df_audit['purity'], df_audit['entropy'], color='#00b894', alpha=0.1, label='Stability Zone')
axes[0].set_title('Option 1: Line Chart (The Gap Audit)')
axes[0].set_ylim(-0.05, 1.1)
axes[0].legend()
axes[0].grid(True, alpha=0.2)

# --- Option 2: Standard Bar (Layer Strength) ---
axes[1].bar(df_audit['layer'], df_audit['purity'], color='#dfe6e9', label='Purity Capacity')
axes[1].bar(df_audit['layer'], df_audit['stability'], color='#00b894', label='Net Stability')
axes[1].set_title('Option 2: Standard Bar (Layer Strength)')
axes[1].legend()

# --- Option 3: Stacked Bar (Compositional Audit) ---
axes[2].bar(df_audit['layer'], df_audit['stability'], label='Stability (Coherence)', color='#00b894')
axes[2].bar(df_audit['layer'], df_audit['entropy'], bottom=df_audit['stability'], label='Entropy (Noise)', color='#d63031')
axes[2].set_title('Option 3: Stacked Bar (Compositional Audit)')
axes[2].set_ylim(0, 1.1)
axes[2].legend()

plt.tight_layout()
plt.show()

