import os
import pennylane as qml
from pennylane import numpy as np

# ==========================================
# 1. API CONFIGURATION
# ==========================================
# Replace with your actual IonQ API key
IONQ_API_KEY = "YOUR_IONQ_API_KEY_HERE"
os.environ["IONQ_API_KEY"] = IONQ_API_KEY

# Target options: "ionq.simulator" (for testing) or "ionq.qpu" (for actual QPU execution)
IONQ_TARGET = "ionq.simulator"

# ==========================================
# 2. DEVICE SETUP
# ==========================================
NUM_QUBITS = 2
dev = qml.device(IONQ_TARGET, wires=NUM_QUBITS, shots=1000)

# ==========================================
# 3. QUANTUM CIRCUIT DEFINITION
# ==========================================
@qml.qnode(dev)
def ionq_circuit(params):
    """
    Sample quantum circuit: Entangles qubits and applies single-qubit rotations.
    Adapt this circuit to your specific Mo Project state preparation.
    """
    # Initialize superposition
    qml.Hadamard(wires=0)

    # Entangle qubits
    qml.CNOT(wires=[0, 1])

    # Parametric rotations (e.g., modeling molecular state transitions)
    qml.RY(params[0], wires=0)
    qml.RZ(params[1], wires=1)

    # Return output probabilities across all computational basis states
    return qml.probs(wires=list(range(NUM_QUBITS)))

# ==========================================
# 4. EXECUTION & RESULTS FETCHING
# ==========================================
if __name__ == "__main__":
    print(f"🚀 Initializing job submission to IonQ ({IONQ_TARGET})...")

    # Parameters for the circuit gates
    test_params = np.array([np.pi / 4, np.pi / 2], requires_grad=False)

    try:
        # Submit job to IonQ API and retrieve results
        results = ionq_circuit(test_params)

        print("\n✅ Job successfully executed on IonQ!")
        print("-" * 40)
        print("State Probabilities [|00>, |01>, |10>, |11>]:")
        for i, prob in enumerate(results):
            basis_state = format(i, f'0{NUM_QUBITS}b')
            print(f"  |{basis_state}⟩ : {prob:.4f}")
        print("-" * 40)

    except Exception as e:
        print(f"\n❌ Error submitting to IonQ: {e}")

