import pennylane as qml
from pennylane import numpy as np

# 1. Define the device
# For local simulation:
dev = qml.device("default.qubit", wires=2, shots=1000)
# To use IonQ hardware later, swap with:
# dev = qml.device("ionq.qpu", wires=2, shots=1000, device="ionq_harmony")

@qml.qnode(dev)
def chsh_circuit(phi_a, phi_b):
    # Prepare Bell State: (|00> + |11>) / sqrt(2)
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])

    # Apply rotation gates to change measurement basis
    qml.RY(phi_a, wires=0)
    qml.RY(phi_b, wires=1)

    return qml.counts(wires=[0, 1])

# 2. CHSH Measurement Function
def calculate_chsh(phi_a1, phi_a2, phi_b1, phi_b2):
    """
    Computes correlation: E = P(00) + P(11) - P(01) - P(10)
    CHSH value S = |E(a1, b1) + E(a1, b2) + E(a2, b1) - E(a2, b2)|
    """
    def get_correlation(pa, pb):
        counts = chsh_circuit(pa, pb)
        total = sum(counts.values())
        # Correlated (00, 11) minus Anticorrelated (01, 10)
        corr = (counts.get('00', 0) + counts.get('11', 0) -
                counts.get('01', 0) - counts.get('10', 0)) / total
        return corr

    e11 = get_correlation(phi_a1, phi_b1)
    e12 = get_correlation(phi_a1, phi_b2)
    e21 = get_correlation(phi_a2, phi_b1)
    e22 = get_correlation(phi_a2, phi_b2)

    return abs(e11 + e12 + e21 - e22)

# Angles for maximal violation
a1, a2 = 0, np.pi/2
b1, b2 = np.pi/4, -np.pi/4

# Run simulation
s_value = calculate_chsh(a1, a2, b1, b2)
print(f"CHSH S-value: {s_value:.4f} (Quantum mechanics predicts ~2.828)")

