import pennylane as qml
from pennylane import numpy as np
import json
import pandas as pd

# 1. Setup Data Collection
# Resetting results_log to clear out non-serializable tensors from previous runs
results_log = []

def save_data(step_name, data):
    results_log.append(data)
    # Save to JSON for metadata
    with open('quantum_research.json', 'w') as f:
        json.dump(results_log, f)
    # Save to CSV for analysis
    pd.DataFrame(results_log).to_csv('quantum_research.csv', index=False)

# 2. Define the VQE Circuit (Resource Efficient)
dev = qml.device("default.qubit", wires=4)

@qml.qnode(dev)
def atomic_circuit(params):
    # Encoding atomic state
    for i in range(4):
        qml.RY(params[i], wires=i)
    qml.CNOT(wires=[0, 1])
    return qml.expval(qml.Hamiltonian([1.0], [qml.PauliZ(0)]))

# 3. Execution Pipeline
def run_pipeline(params):
    # Step A: Classical Calculation
    energy = atomic_circuit(params)

    # Step B: Record State
    # Ensure both params and energy are converted to base Python types
    record = {
        "step": "atomic_simulation",
        "params": [p.item() for p in params],
        "energy": energy.item()
    }
    save_data("run_1", record)
    return energy

# Run
initial_params = np.array([0.1, 0.2, 0.3, 0.4], requires_grad=True)
run_pipeline(initial_params)
print("Pipeline successful: Data saved to JSON/CSV.")

