import pennylane as qml
from pennylane import numpy as np

# Final Verification of the Nucleus Layer Stability
dev_verify = qml.device('default.mixed', wires=4)

@qml.qnode(dev_verify)
def verify_nucleus_state(noise_p=0.05):
    # Optimized state preparation
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])

    # Add noise to simulate environment
    for i in range(2):
        qml.DepolarizingChannel(noise_p, wires=i)

    return qml.density_matrix(wires=[0, 1])

# Execute
rho_final = verify_nucleus_state()
purity_final = np.real(np.trace(np.matmul(rho_final, rho_final)))
entropy_final = qml.math.vn_entropy(rho_final, indices=[0, 1])

print(f'--- Final Pipeline Audit ---')
print(f'Nucleus Purity: {float(purity_final):.4f}')
print(f'Nucleus Entropy: {float(entropy_final):.4f}')
print(f'Stability Score: {float(purity_final - entropy_final):.4f}')

