dev = qml.device("default.qubit", wires=num_qubits)

def run_quantum_sweep():
    sf_range = np.linspace(1.5, 3.5, 20)
    em_range = np.linspace(-2.0, -0.5, 20)
    landscape = []
    wf, zpe, cross, flux = 0.7, 0.13, 0.45, 0.25

    obs = [
        qml.PauliZ(0) @ qml.PauliZ(1),
        qml.PauliX(0),
        qml.PauliZ(2),
        qml.Identity(3),
        qml.PauliZ(0) @ qml.PauliZ(2),
        qml.PauliY(0) @ qml.PauliY(1)
    ]

    for sf in sf_range:
        for em in em_range:
            coeffs = [float(sf), wf, float(em), zpe, cross, flux]
            H = qml.Hamiltonian(coeffs, obs)

            @qml.qnode(dev)
            def circuit():
                qml.RY(0.5, wires=0)
                qml.CNOT(wires=[0, 1])
                qml.RZ(0.2, wires=2)
                qml.RX(0.1, wires=3)
                return qml.expval(H)

            energy = float(circuit())
            landscape.append({'strong': float(sf), 'em': float(em), 'energy': energy})

    return landscape

def run_entanglement_audit():
    @qml.qnode(dev)
    def get_state():
        qml.Hadamard(wires=0)
        qml.CNOT(wires=[0, 1])
        qml.RY(0.3, wires=2)
        qml.RX(0.1, wires=3)
        return qml.state()

    state = get_state()
    rho = qml.math.dm_from_state_vector(state)

    audit = []
    layers = [([0, 1], "Nucleus"), ([2], "Electron Cloud"), ([3], "Vacuum Field")]

    for wires, name in layers:
        entropy = float(qml.math.vn_entropy(rho, indices=wires))
        rho_sub = qml.math.reduce_dm(rho, indices=wires)
        purity = float(np.real(np.trace(np.matmul(rho_sub, rho_sub))))
        stability = purity - entropy

        audit.append({
            "layer": name,
            "purity": purity,
            "entropy": entropy,
            "stability": stability
        })

    return audit

landscape_data = run_quantum_sweep()
audit_data = run_entanglement_audit()

