import pennylane as qml
from pennylane import numpy as np
import csv

# 1. Setup Device (Pivoting to local simulator for logic validation)
# We use 'default.mixed' because it supports noise channels like DepolarizingChannel
dev = qml.device("default.mixed", wires=2)

# 2. The Physics Engine: Thermal-Aware Quantum Circuit
def thermal_depolarizing_channel(T, energy_gap=1.0):
    # Mapping thermal energy to leak probability
    return 1 - np.exp(-energy_gap / (T + 1e-6))

@qml.qnode(dev)
def get_density_matrix(T):
    # State Preparation
    qml.Hadamard(wires=0)
    qml.CNOT(wires=[0, 1])

    # Thermal Interaction (The "Leak")
    prob = thermal_depolarizing_channel(T)
    qml.DepolarizingChannel(prob, wires=0)
    qml.DepolarizingChannel(prob, wires=1)

    return qml.density_matrix(wires=[0, 1])

# 3. Execution & Audit Log
def run_final_audit():
    temperatures = [0.1, 0.5, 1.0, 1.5, 2.0]

    print(f"--- Starting Thermal Audit on Local Simulator ---")
    for T in temperatures:
        rho = get_density_matrix(T)
        # Von Neumann Entropy calculation
        entropy = qml.math.vn_entropy(rho, indices=[0, 1])
        # Purity calculation: Tr(rho^2)
        purity = np.real(np.trace(np.matmul(rho, rho)))

        print(f"Temp {T:.1f} | Purity: {purity:.4f} | Entropy: {float(entropy):.4f}")

# Execute the audit
run_final_audit()

"""### Final Audit Selection: The Compositional (Zero-Sum) View
This visualization highlights the trade-off between coherence (Stability) and decoherence (Entropy) within each structural layer.
"""

