"""### Robustness Audit: Introducing Environmental Noise
To measure the 'Decoherence Leak', we will now introduce a `DepolarizingChannel`. This simulates a non-ideal environment where the quantum state has a probability `p` of being scrambled into noise.
"""

# Switching to 'default.mixed' to support noise channels
dev_mixed = qml.device("default.mixed", wires=4)

def run_noisy_audit(noise_probability=0.1):
    @qml.qnode(dev_mixed)
    def get_noisy_state():
        # Replicating core state preparation
        qml.Hadamard(wires=0)
        qml.CNOT(wires=[0, 1])
        qml.RY(0.3, wires=2)
        qml.RX(0.1, wires=3)

        # APPLYING ENVIRONMENTAL NOISE to all layers
        for i in range(4):
            qml.DepolarizingChannel(noise_probability, wires=i)

        return qml.density_matrix(wires=[0, 1, 2, 3])

    rho = get_noisy_state()

    noisy_audit = []
    layers = [([0, 1], "Nucleus"), ([2], "Electron Cloud"), ([3], "Vacuum Field")]

    print(f"--- Noise-Induced Decoherence Audit (p={noise_probability}) ---")
    for wires, name in layers:
        # Calculate entropy (S)
        entropy = float(qml.math.vn_entropy(rho, indices=wires))
        # Calculate purity (P)
        rho_sub = qml.math.reduce_dm(rho, indices=wires)
        purity = float(np.real(np.trace(np.matmul(rho_sub, rho_sub))))
        # Calculate Stability (St = P - S)
        stability = purity - entropy
        # Stability-to-Purity Ratio
        ratio = stability / purity

        noisy_audit.append({"layer": name, "ratio": ratio, "leak": 1.0 - ratio})
        print(f"Layer: {name:<15} | S/P Ratio: {ratio:.4f} | Leak: {1.0-ratio:.4f}")

    return noisy_audit

# Execute the noisy audit
noisy_results = run_noisy_audit(noise_probability=0.05)

"""### Quantitative Analysis of the Decoherence Leak
In this final audit, we compare the 'Leak' values. A higher leak indicates that a layer is converting quantum coherence into classical noise more rapidly under the pressure of environmental depolarizing forces.

### Final Project Report: Decoherence Leak Audit Summary

**Objective:** To quantify the impact of environmental noise (`DepolarizingChannel`) on a three-layer quantum system.

**Core Findings:**
*   **Nucleus (Wires 0,1):** Most vulnerable layer. Showed a **Leak of 0.5175**, indicating it retains less than half of its original coherence under the tested noise profile ($p=0.05$).
*   **Peripheral Layers:** The Electron Cloud and Vacuum Field demonstrated higher relative stability with a **Leak of ~0.1562**.
*   **Quantum-to-Classical Transition:** The Nucleus has effectively transitioned to a mixed state where classical noise dominates its quantum properties.

**Recommendation:**
Future iterations should transition to **Discovery** by implementing error-correction codes (like the Shor code) specifically on the Nucleus wires to mitigate this disproportionate leak.
"""

