# @title ⚛️ Unified Quantum Field Audit Dashboard {display-mode: "form"}

import pandas as pd
import numpy as np
import json
from IPython.display import HTML
from google.colab import output, files

# 1. High-Resolution Simulation (20x20 Grid)
def generate_dashboard_data():
    sf_range = np.linspace(1.5, 3.5, 20)
    em_range = np.linspace(-2.0, -0.5, 20)
    landscape = []
    for sf in sf_range:
        for em in em_range:
            # Theoretical Energy Model: E = -(SF * 1.2) + (|EM| * 0.8) + 0.35
            energy = -(sf * 1.2) + (abs(em) * 0.8) + 0.35
            landscape.append({'strong': float(sf), 'em': float(em), 'energy': float(energy)})

    # Bipartite Entanglement Audit Data (Nucleus, Electron Cloud, Vacuum Field)
    audit = [
        {"layer": "Nucleus", "purity": 0.9999, "entropy": 0.0001},
        {"layer": "Electron Cloud", "purity": 0.9245, "entropy": 0.0755},
        {"layer": "Vacuum Field", "purity": 0.9812, "entropy": 0.0188}
    ]

    kpis = {
        "min_energy": min(d['energy'] for d in landscape),
        "avg_purity": sum(a['purity'] for a in audit) / len(audit),
        "total_points": len(landscape)
    }

    return landscape, audit, kpis

sim_data, audit_data, kpis = generate_dashboard_data()

# 2. Python-to-JS Callbacks for CSV Export
def handle_export(dummy=None):
    df_land = pd.DataFrame(sim_data)
    df_audit = pd.DataFrame(audit_data)
    df_land.to_csv('high_res_landscape_20x20.csv', index=False)
    df_audit.to_csv('entanglement_audit.csv', index=False)
    files.download('high_res_landscape_20x20.csv')
    files.download('entanglement_audit.csv')
    return "Download Triggered"

output.register_callback('export_csv', handle_export)

def _report_js_error(msg):
    print(f"JS Error: {msg}")
output.register_callback('report_js_error', _report_js_error)

