import os
import numpy as np
import matplotlib.pyplot as plt
from mpl_toolkits.mplot3d import Axes3D

# Qiskit & IonQ imports
from qiskit import QuantumCircuit
from qiskit_ionq import IonQProvider

print("="*60)
print("🌌 PART 1: THE ATOM FUZZY BALL (3D PROBABILITY CLOUD)")
print("="*60)
# We simulate the true "fuzzy" nature of a 1s atomic orbital
# (The probability cloud for both matter and antimatter looks exactly like this)

# 1. Generate a massive 3D grid of random points
N = 100000
x = np.random.randn(N) * 2
y = np.random.randn(N) * 2
z = np.random.randn(N) * 2

# Calculate distance from the nucleus (r)
r = np.sqrt(x**2 + y**2 + z**2)

# 2. Apply the raw math: Probability density for a 1s orbital decays exponentially
probability_density = np.exp(-2 * r)

# 3. Use random thresholding to filter points (creating the "fuzziness")
random_threshold = np.random.rand(N)
fuzzy_mask = random_threshold < probability_density

x_fuzzy = x[fuzzy_mask]
y_fuzzy = y[fuzzy_mask]
z_fuzzy = z[fuzzy_mask]

# 4. Render the 3D Fuzzy Ball
fig = plt.figure(figsize=(8, 8))
ax = fig.add_subplot(111, projection='3d')

# Color the points based on their distance from the center to look like glowing energy
colors = np.linalg.norm([x_fuzzy, y_fuzzy, z_fuzzy], axis=0)
ax.scatter(x_fuzzy, y_fuzzy, z_fuzzy, c=colors, cmap='plasma', alpha=0.15, s=10, edgecolors='none')

ax.set_title("The 'Fuzzy Ball' Atom (Electron/Positron Probability Cloud)")
ax.set_xlabel("X (Space)")
ax.set_ylabel("Y (Space)")
ax.set_zlabel("Z (Space)")

# Hide the grid panes so it looks like it's floating in empty space
ax.xaxis.pane.fill = False
ax.yaxis.pane.fill = False
ax.zaxis.pane.fill = False
ax.grid(False)
plt.show()


print("\n" + "="*60)
print("⚡ PART 2: MINIMAL QUBIT ENERGY MAPPING ON IONQ")
print("="*60)
print("Modeling the Matter-Energy duality state with just 1 Qubit...")

# Setup IonQ Provider
# Replace the string below with your actual API key from your IonQ dashboard
API_KEY = "YOUR_IONQ_API_KEY_HERE"

try:
    if API_KEY == "YOUR_IONQ_API_KEY_HERE":
        print("\n⚠️ Note: You need to paste your real IonQ API Key into the code to run the quantum circuit!")
    else:
        provider = IonQProvider(API_KEY)
        backend = provider.get_backend("simulator") # Uses the ideal IonQ simulator

        # We slice the problem down to the bare minimum:
        # 1 qubit representing a 2-level energy system (Ground State vs Excited State)
        qc = QuantumCircuit(1, 1)

        # A Hadamard gate puts the atom in a perfect superposition
        # (It exists as a 'fuzzy' combination of states until observed)
        qc.h(0)

        # We observe the atom (collapsing the fuzzy probability)
        qc.measure(0, 0)

        print("\nSending raw quantum math to IonQ Simulator...")
        job = backend.run(qc, shots=1000)
        counts = job.result().get_counts()

        print("\n✅ Results from IonQ (1000 observations):")
        print(f"State '0' (Matter/Ground):   {counts.get('0', 0)} times")
        print(f"State '1' (Energy/Excited):  {counts.get('1', 0)} times")
        print("\nNotice how the math perfectly balances the probability, just like the 3D fuzzy ball!")

except Exception as e:
    print(f"\n❌ Quantum Execution Error: {e}")

