import pennylane as qml
from pennylane import numpy as np

# 1. Define 3D Search Space
# We vary all three primary force parameters
sf_range = py_np.linspace(1.5, 3.5, 4)
wf_range = py_np.linspace(0.1, 1.5, 4)
em_range = py_np.linspace(-2.0, -0.5, 4)

results_3d = []

print(f"--- Starting 3D Unified Field Sweep ({len(sf_range)*len(wf_range)*len(em_range)} configurations) ---")

for sf in sf_range:
    for wf in wf_range:
        for em in em_range:
            # Hamiltonian coefficients: [Strong, Weak, EM, Identity, Z0Z2, Y0Y1]
            current_coeffs = [float(sf), float(wf), float(em), 0.13, 0.45, 0.25]
            current_H = qml.Hamiltonian(current_coeffs, obs)

            @qml.qnode(dev)
            def sweep_circuit(params):
                qml.RX(params[0], wires=3)
                qml.RY(params[1], wires=0)
                qml.RY(params[2], wires=1)
                qml.CNOT(wires=[0, 1])
                qml.RZ(params[3], wires=2)
                qml.CRZ(params[0], wires=[0, 2])
                qml.CZ(wires=[1, 2])
                return qml.expval(current_H)

            # Quick optimization for each point
            p = np.array([0.15, 0.22, 0.38, 0.41], requires_grad=True)
            opt = qml.GradientDescentOptimizer(stepsize=0.6)
            for _ in range(30):
                p = opt.step(sweep_circuit, p)

            energy = float(sweep_circuit(p))
            results_3d.append({
                'strong': sf, 'weak': wf, 'em': em, 'energy': energy, 'params': p.tolist()
            })

# Find Global Minimum in 3D Space
best_state = min(results_3d, key=lambda x: x['energy'])
print(f"\nGlobal Minimum Found:")
print(f"Strong: {best_state['strong']:.2f} | Weak: {best_state['weak']:.2f} | EM: {best_state['em']:.2f}")
print(f"Energy: {best_state['energy']:.6f}")







# 2. Entanglement Audit at the New Global Minimum
@qml.qnode(dev)
def get_optimal_state(params):
    qml.RX(params[0], wires=3)
    qml.RY(params[1], wires=0)
    qml.RY(params[2], wires=1)
    qml.CNOT(wires=[0, 1])
    qml.RZ(params[3], wires=2)
    qml.CRZ(params[0], wires=[0, 2])
    qml.CZ(wires=[1, 2])
    return qml.state()

state_vec = get_optimal_state(np.array(best_state['params']))
rho_nucleus = qml.math.dm_from_state_vector(state_vec)
# Measure entropy of the Nucleus (wires 0, 1)
entropy_val = float(qml.math.vn_entropy(rho_nucleus, indices=[0, 1]))

print(f"--- Post-Sweep Entanglement Audit ---")
print(f"Von Neumann Entropy (Nucleus): {entropy_val:.6f}")
if entropy_val > 0.1: print("Status: Non-trivial entanglement detected between field layers.")
else: print("Status: Field layers remain relatively separable.")

