import pennylane
print(f"PennyLane version: {pennylane.__version__}")

import pennylane as qml
from pennylane import numpy as np

# =====================================================================
# EXPANDED QUANTUM PROJECT: COMPLEX UNIFIED FIELD CONTROL
# Features: Long-range coupling and Non-Abelian Gauge simulation terms
# =====================================================================

num_qubits = 4
dev = qml.device("default.qubit", wires=num_qubits)

# Expanded Coefficients for a more complex energy landscape
coeffs = [
    2.5,   # Strong Nuclear Force (Z0 Z1)
    0.7,   # Weak Nuclear Force (X0)
    -1.2,  # Electromagnetic Force (Z2)
    0.13,  # Zero-Point Energy (Identity)
    0.45,  # NEW: Cross-Field Coupling (Z0 Z2)
    0.25   # NEW: Flux Term (Y0 Y1) representing gauge field curvature
]

obs = [
    qml.PauliZ(0) @ qml.PauliZ(1),
    qml.PauliX(0),
    qml.PauliZ(2),
    qml.Identity(3),
    qml.PauliZ(0) @ qml.PauliZ(2),  # Long-range force coupling
    qml.PauliY(0) @ qml.PauliY(1)   # Complex phase interaction
]

H_complex = qml.Hamiltonian(coeffs, obs)

@qml.qnode(dev)
def quantum_project_circuit(params):
    # 1. THE VACUUM LAYER
    qml.RX(params[0], wires=3)

    # 2. SUBATOMIC LAYER
    qml.RY(params[1], wires=0)
    qml.RY(params[2], wires=1)
    qml.CNOT(wires=[0, 1])

    # 3. ATOMIC LAYER
    qml.RZ(params[3], wires=2)

    # 4. CROSS-LAYER ENTANGLEMENT (Simulating Unified Field effects)
    qml.CRZ(params[0], wires=[0, 2])
    qml.CZ(wires=[1, 2])

    return qml.expval(H_complex)

def optimize_system(steps=50, lr=0.4):
    params = np.array([0.15, 0.22, 0.38, 0.41], requires_grad=True)
    opt = qml.GradientDescentOptimizer(stepsize=lr)
    energies = []

    print(f"--- Launching Complex Hamiltonian Simulation ({steps} steps) ---")
    for i in range(steps):
        params, energy = opt.step_and_cost(quantum_project_circuit, params)
        energies.append(float(energy))
        if (i+1) % 10 == 0:
            print(f"Step {i+1:02d} | Energy: {energy:.7f}")

    return energies

if __name__ == '__main__':
    complex_energies = optimize_system()
    print(f"Final Ground State Energy: {complex_energies[-1]:.7f}")

import matplotlib.pyplot as plt

# Test the optimal LR (0.6) on the complex Hamiltonian
steps_comp = 100
lr_fast = 0.6
lr_base = 0.4

print(f"--- Comparing LR={lr_base} vs LR={lr_fast} on Complex System ---")
energies_base = optimize_system(steps=steps_comp, lr=lr_base)
energies_fast = optimize_system(steps=steps_comp, lr=lr_fast)

# Visualization
plt.figure(figsize=(10, 6))
plt.plot(energies_base, label=f'Base LR ({lr_base})', color='gray', linestyle='--')
plt.plot(energies_fast, label=f'Optimal LR ({lr_fast})', color='crimson', linewidth=2)
plt.title('Performance Comparison: Complex Hamiltonian Optimization')
plt.xlabel('Optimization Step')
plt.ylabel('Energy')
plt.legend()
plt.grid(True, alpha=0.3)
plt.show()

print(f"\nFinal Energy (LR=0.4): {energies_base[-1]:.8f}")
