# Ensure `dev` and `hyper_bridge_ansatz` are defined from previous cells
# Assuming `dev` and `hyper_bridge_ansatz` are globally accessible from their definitions above.

@qml.qnode(dev)
def get_full_system_state_for_eigvals(params):
    hyper_bridge_ansatz(params, layers=30)
    return qml.state()

# Use the results from the hyper-bridge optimization (res_hyper.x should be available from the previous run)
if 'res_hyper' in globals():
    final_optimized_params = res_hyper.x

    # Get the full system state vector at the optimal parameters
    full_state_vector = get_full_system_state_for_eigvals(final_optimized_params)

    # Convert the state vector to a density matrix
    global_rho_for_eigvals = qml.math.dm_from_state_vector(full_state_vector)

    # Calculate the eigenvalues of the full system density matrix
    eigenvalues = np.linalg.eigvalsh(global_rho_for_eigvals)

    # Sort eigenvalues in descending order
    sorted_eigenvalues = np.sort(eigenvalues)[::-1]

    print("--- Full System Density Matrix Eigenvalues ---")
    print(f"All eigenvalues: {sorted_eigenvalues}")

    # Plotting the eigenvalues
    plt.figure(figsize=(10, 6))
    plt.bar(range(len(sorted_eigenvalues)), sorted_eigenvalues, color='skyblue')
    plt.title('Eigenvalue Spectrum of the Full System Density Matrix')
    plt.xlabel('Eigenvalue Index')
    plt.ylabel('Magnitude')
    plt.grid(axis='y', linestyle='--', alpha=0.7)
    plt.axhline(y=1.0, color='red', linestyle=':', label='Ideal Pure State (1.0)')
    plt.legend()
    plt.show()

    # Purity check based on eigenvalues
    purity = np.sum(eigenvalues**2)
    print(f"\nGlobal Purity (sum of squared eigenvalues): {purity:.6f}")

    if np.isclose(purity, 1.0, atol=1e-3):
        print("Observation: The system is in a pure state. All entropy observed in subsystems is due to entanglement.")
    else:
        print("Observation: The system is in a mixed state. Subsystem entropy may be due to a combination of entanglement and classical mixing/noise.")
else:
    print("Error: 'res_hyper' (optimization results) not found. Please ensure the optimization cell (75da8062) has been run.")

"""### Step 2: Global Purity Audit
After running the Hyper-Bridge optimization, we must ensure the system remains in a **Pure State**. High subsystem entropy is only valid evidence of non-locality if the global system purity $\text{Tr}(\rho^2) \approx 1$.
"""

import pennylane as qml
from pennylane import numpy as np

@qml.qnode(dev)
def get_full_system_state(params):
    hyper_bridge_ansatz(params, layers=30)
    return qml.state()

# Use the results from the hyper-bridge optimization
if 'res_hyper' in globals():
    full_state = get_full_system_state(res_hyper.x)
    global_rho = qml.math.dm_from_state_vector(full_state)
    global_purity = np.real(qml.math.trace(qml.math.matmul(global_rho, global_rho)))

    print(f"--- Global State Audit ---")
    print(f"Global Purity: {global_purity:.6f}")

    if np.isclose(global_purity, 1.0, atol=1e-2):
        print("CONFIRMED: The system is PURE. The entropy breach represents true quantum entanglement.")
    else:
        print("WARNING: Low purity detected. The entropy may be due to optimization noise or mixedness.")
else:
    print("Error: Please run cell 75da8062 (the optimization) before executing this audit.")

