import pennylane as qml
from pennylane import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns

# 1. Define Pauli basis for 2-qubit tomography (15 operators + Identity)
pauli_ops = {
    "II": qml.Identity(0) @ qml.Identity(1),
    "IX": qml.Identity(0) @ qml.PauliX(1),
    "IY": qml.Identity(0) @ qml.PauliY(1),
    "IZ": qml.Identity(0) @ qml.PauliZ(1),
    "XI": qml.PauliX(0) @ qml.Identity(1),
    "XX": qml.PauliX(0) @ qml.PauliX(1),
    "XY": qml.PauliX(0) @ qml.PauliY(1),
    "XZ": qml.PauliX(0) @ qml.PauliZ(1),
    "YI": qml.PauliY(0) @ qml.Identity(1),
    "YX": qml.PauliY(0) @ qml.PauliX(1),
    "YY": qml.PauliY(0) @ qml.PauliY(1),
    "YZ": qml.PauliY(0) @ qml.PauliZ(1),
    "ZI": qml.PauliZ(0) @ qml.Identity(1),
    "ZX": qml.PauliZ(0) @ qml.PauliX(1),
    "ZY": qml.PauliZ(0) @ qml.PauliY(1),
    "ZZ": qml.PauliZ(0) @ qml.PauliZ(1)
}

@qml.qnode(dev)
def measure_pauli_basis(params, obs):
    universal_entangler_ansatz(params)
    return qml.expval(obs)

# 2. Collect expectation values using the best parameters from res_tracked
expectations = {}
for label, op in pauli_ops.items():
    expectations[label] = float(measure_pauli_basis(res_tracked.x, op))

# 3. Reconstruct Density Matrix: rho = 1/4 * sum( <O> * O )
def reconstruct_rho(exp_dict):
    rho = np.zeros((4, 4), dtype=complex)
    for label, val in exp_dict.items():
        # Get matrix representation of the Pauli string
        mat = qml.matrix(pauli_ops[label], wire_order=[0, 1])
        rho += val * mat
    return rho / 4.0

rho_reconstructed = reconstruct_rho(expectations)

# 4. Visualization of Real and Imaginary parts
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 6))

sns.heatmap(np.real(rho_reconstructed), annot=True, fmt=".3f", cmap="RdBu_r", center=0, ax=ax1)
ax1.set_title("Reconstructed Density Matrix (Real Part)")

sns.heatmap(np.imag(rho_reconstructed), annot=True, fmt=".3f", cmap="PRGn", center=0, ax=ax2)
ax2.set_title("Reconstructed Density Matrix (Imaginary Part)")

plt.tight_layout()
plt.show()

# Calculate Purity to check state quality
purity = np.real(np.trace(np.dot(rho_reconstructed, rho_reconstructed)))
print(f"--- Tomography Report ---")
print(f"State Purity: {purity:.6f} (1.0 = Pure State)")
print(f"Entropy (Re-calculated from QST): {float(qml.math.vn_entropy(rho_reconstructed, indices=[0, 1])):.6f}")

