import scipy.optimize
import matplotlib.pyplot as plt
import pennylane as qml
from pennylane import numpy as np

# 1. Define range of layers to test
layer_counts = [2, 4, 8, 12, 16, 20, 24]
fidelity_results = []

# Target Bell State
bell_state = np.array([1, 0, 0, 1]) / np.sqrt(2)
rho_target = np.outer(bell_state, np.conj(bell_state))

print("--- Starting Layer Sensitivity Analysis ---")

for layers in layer_counts:
    # Define specific ansatz for this layer count
    def temp_ansatz(params):
        param_idx = 0
        for l in range(layers):
            for i in range(4):
                qml.Rot(params[param_idx], params[param_idx+1], params[param_idx+2], wires=i)
                param_idx += 3
            qml.SWAP(wires=[0, 3])
            qml.CH(wires=[1, 2])
            for i in range(4):
                qml.IsingXY(params[param_idx], wires=[i, (i + 1) % 4])
                param_idx += 1
            qml.MultiRZ(params[param_idx], wires=[0, 1, 2, 3])
            param_idx += 1

    @qml.qnode(dev)
    def temp_cost(params):
        temp_ansatz(params)
        return qml.expval(H_bridge)

    @qml.qnode(dev)
    def get_nucleus_dm(params):
        temp_ansatz(params)
        return qml.density_matrix(wires=[0, 1])

    # Initialize and optimize (L-BFGS-B)
    params_needed = layers * (12 + 4 + 1)
    init_p = np.random.uniform(-np.pi, np.pi, params_needed, requires_grad=True)
    res_temp = scipy.optimize.minimize(temp_cost, init_p, method='L-BFGS-B', options={'maxiter': 50})

    # Extract Reduced Density Matrix and calculate Fidelity
    rho_nuc = get_nucleus_dm(res_temp.x)
    fid = np.real(np.trace(np.dot(rho_nuc, rho_target)))

    fidelity_results.append(fid)
    print(f"Layers: {layers:02d} | Fidelity: {fid:.6f} | Energy: {res_temp.fun:.4f}")

# Visualization
plt.figure(figsize=(10, 6))
plt.plot(layer_counts, fidelity_results, marker='o', color='darkviolet', linewidth=2)
plt.title('Bridge Depth Sensitivity: Nucleus Fidelity vs Layers')
plt.xlabel('Number of Ansatz Layers')
plt.ylabel('Fidelity to |Phi+>')
plt.grid(True, linestyle=':', alpha=0.6)
plt.show()

