import scipy.optimize
import matplotlib.pyplot as plt
import pennylane as qml
from pennylane import numpy as np

# 1. Redefine Cost Function to Maximize Entropy
@qml.qnode(dev)
def get_reduced_dm_optimized(params):
    universal_entangler_ansatz(params, layers=10)
    return qml.density_matrix(wires=[0, 1])

def entropy_cost_max(params):
    rho = get_reduced_dm_optimized(params)
    # Calculate Von Neumann Entropy
    evs = qml.math.eigvalsh(rho)
    evs = evs[evs > 1e-15]
    ent = -qml.math.sum(evs * qml.math.log2(evs))
    # We minimize (1.0 - Entropy) to drive entropy toward 1.0 (Max for 2 qubits)
    return float(1.0 - qml.math.real(ent))

# 2. Optimization Setup
num_layers = 10
total_params_ent = num_layers * (12 + 4 + 1)
init_params_ent = np.random.uniform(-np.pi, np.pi, total_params_ent, requires_grad=True)

entropy_tracking = []

def cb_ent(p):
    current_cost = entropy_cost_max(p)
    entropy_tracking.append(1.0 - current_cost)

print(f"--- Maximizing Subsystem Entanglement (Layers: {num_layers}) ---")
res_ent = scipy.optimize.minimize(
    entropy_cost_max,
    init_params_ent,
    method='L-BFGS-B',
    callback=cb_ent,
    options={'maxiter': 100}
)

# 3. Final State Capture for Diagnostic
rho_nuc_psi = get_reduced_dm_optimized(res_ent.x)
final_entropy = 1.0 - res_ent.fun

# Visualization
plt.figure(figsize=(10, 6))
plt.plot(entropy_tracking, color='#e67e22', linewidth=2.5, label='Entropy Path')
plt.axhline(y=1.0, color='red', linestyle='--', alpha=0.5, label='Maximal Entanglement (1.0)')
plt.title('Optimization for Maximal Nucleus Entanglement')
plt.xlabel('Iteration')
plt.ylabel('Von Neumann Entropy')
plt.legend()
plt.grid(True, alpha=0.3)
plt.show()

print(f"Final Achieved Entropy: {final_entropy:.6f}")
print(f"Purity: {np.real(np.trace(np.dot(rho_nuc_psi, rho_nuc_psi))):.6f}")

import scipy.optimize
import matplotlib.pyplot as plt
import pennylane as qml
from pennylane import numpy as np

# 1. Setup for Multi-Depth Comparison
depths_to_test = [2, 6, 10]
convergence_history = {}

def run_depth_trial(layers, max_iter=40):
    total_p = layers * (12 + 4 + 1)
    init_p = np.random.uniform(-np.pi, np.pi, total_p, requires_grad=True)

    current_trial_entropy = []

    def cost_fn(p):
        # Helper within the loop to use the correct layer count
        @qml.qnode(dev)
        def get_dm(params):
            universal_entangler_ansatz(params, layers=layers)
            return qml.density_matrix(wires=[0, 1])

        rho = get_dm(p)
        evs = qml.math.eigvalsh(rho)
        evs = evs[evs > 1e-15]
        ent = -qml.math.sum(evs * qml.math.log2(evs))
        return float(2.0 - qml.math.real(ent))

    def callback(p):
        current_trial_entropy.append(2.0 - cost_fn(p))

    print(f"Optimizing Depth: {layers} layers...")
    scipy.optimize.minimize(
        cost_fn, init_p, method='L-BFGS-B',
        callback=callback, options={'maxiter': max_iter}
    )
    return current_trial_entropy

# 2. Execute Trials
for d in depths_to_test:
    convergence_history[d] = run_depth_trial(d)

# 3. Visualization
plt.figure(figsize=(10, 6))
for d, history in convergence_history.items():
    plt.plot(history, label=f'{d} Layers', linewidth=2)

plt.axhline(y=2.0, color='red', linestyle='--', alpha=0.3, label='Theoretical Max')
plt.title('Entropy Convergence Speed vs. Circuit Depth')
plt.xlabel('Optimization Iteration')
plt.ylabel('Subsystem Entropy')
plt.legend()
plt.grid(True, alpha=0.2)
plt.show()

