import pennylane as qml
from pennylane import numpy as np
import scipy.optimize

# Redefining the ansatz with enhanced Vacuum coupling
def enhanced_bridge_ansatz(params, layers=20):
    param_idx = 0
    for l in range(layers):
        for i in range(4):
            qml.Rot(params[param_idx], params[param_idx+1], params[param_idx+2], wires=i)
            param_idx += 3

        # ENHANCED COUPLING: Direct Vacuum links
        qml.CNOT(wires=[0, 3])  # Nucleus W0 to Vacuum W3
        qml.CNOT(wires=[2, 3])  # Electron Cloud W2 to Vacuum W3
        qml.CZ(wires=[1, 3])    # Nucleus W1 to Vacuum W3 (Phase coupling)

        for i in range(4):
            qml.IsingXY(params[param_idx], wires=[i, (i + 1) % 4])
            param_idx += 1

        qml.MultiRZ(params[param_idx], wires=[0, 1, 2, 3])
        param_idx += 1

@qml.qnode(dev)
def enhanced_cost_fn(params):
    enhanced_bridge_ansatz(params)
    return qml.expval(H_bridge)

# Re-optimizing with the enhanced vacuum bridge
total_p_enhanced = 20 * (12 + 4 + 1)
init_p_enhanced = np.random.uniform(-np.pi, np.pi, total_p_enhanced, requires_grad=True)

print("--- Optimizing Enhanced Vacuum Bridge ---")
res_enhanced = scipy.optimize.minimize(
    enhanced_cost_fn,
    init_p_enhanced,
    method='L-BFGS-B',
    options={'maxiter': 200}
)

@qml.qnode(dev)
def get_enhanced_entropy(params, wire):
    enhanced_bridge_ansatz(params)
    return qml.vn_entropy(wires=[wire])

