import matplotlib.pyplot as plt

def test_gate_efficiency(gate_type='CNOT'):
    def ansatz(params, layers=10):
        param_idx = 0
        for l in range(layers):
            for i in range(4):
                qml.Rot(params[param_idx], params[param_idx+1], params[param_idx+2], wires=i)
                param_idx += 3

            if gate_type == 'CNOT':
                qml.CNOT(wires=[0, 3])
                qml.CNOT(wires=[2, 3])
            elif gate_type == 'CZ':
                qml.CZ(wires=[0, 3])
                qml.CZ(wires=[2, 3])
            elif gate_type == 'Hybrid':
                qml.CNOT(wires=[0, 3])
                qml.CZ(wires=[1, 3])

            for i in range(4):
                qml.IsingXY(params[param_idx], wires=[i, (i + 1) % 4])
                param_idx += 1
            qml.MultiRZ(params[param_idx], wires=[0, 1, 2, 3])
            param_idx += 1

    @qml.qnode(dev)
    def cost_fn(params):
        ansatz(params)
        return qml.expval(H_bridge)

    @qml.qnode(dev)
    def get_entropy(params):
        ansatz(params)
        return qml.vn_entropy(wires=[3])

    n_params = 10 * (12 + 4 + 1)
    res = scipy.optimize.minimize(cost_fn, np.random.uniform(-np.pi, np.pi, n_params), method='L-BFGS-B', options={'maxiter': 50})
    return float(get_entropy(res.x))

gates = ['CNOT', 'CZ', 'Hybrid']
entropies = [test_gate_efficiency(g) for g in gates]

plt.figure(figsize=(8, 5))
plt.bar(gates, entropies, color=['#3498db', '#9b59b6', '#e67e22'])
plt.title('Vacuum (W3) Entropy vs. Bridging Gate Type')
plt.ylabel('Von Neumann Entropy')
plt.show()

for g, e in zip(gates, entropies):
    print(f"{g} Gate Strategy Entropy: {e:.6f}")

"""### Quantifying Scaling: Iterations to Convergence vs. Depth
To move beyond visual inspection, we will now formally measure the number of iterations required for each circuit depth to reach a target entropy threshold ($S_{target} = 1.95$). This will help us identify if the relationship is linear or if we encounter a 'complexity ceiling'.
"""

def iterations_to_threshold(layers, threshold=1.95, max_iter=100):
    total_p = layers * (12 + 4 + 1)
    init_p = np.random.uniform(-np.pi, np.pi, total_p, requires_grad=True)

    # We will use a list to track how many steps were taken
    step_counter = [0]
    convergence_step = max_iter

    def cost_fn(p):
        @qml.qnode(dev)
        def get_dm(params):
            universal_entangler_ansatz(params, layers=layers)
            return qml.density_matrix(wires=[0, 1])

        rho = get_dm(p)
        evs = qml.math.eigvalsh(rho)
        evs = evs[evs > 1e-15]
        ent = -qml.math.sum(evs * qml.math.log2(evs))
        return float(2.0 - qml.math.real(ent))

    def callback(p):
        step_counter[0] += 1
        current_entropy = 2.0 - cost_fn(p)
        # If we cross the threshold, we could stop, but for L-BFGS-B
        # we'll just record the first time it happened.
        nonlocal convergence_step
        if current_entropy >= threshold and convergence_step == max_iter:
            convergence_step = step_counter[0]

    scipy.optimize.minimize(
        cost_fn, init_p, method='L-BFGS-B',
        callback=callback, options={'maxiter': max_iter}
    )
    return convergence_step

# Test range of depths
test_depths = [2, 4, 6, 8, 10, 12, 14]
steps_needed = []

print(f"--- Analyzing Convergence Scaling (Threshold: 1.95) ---")
for d in test_depths:
    steps = iterations_to_threshold(d)
    steps_needed.append(steps)
    print(f"Depth {d:02d}: reached threshold in {steps} iterations.")

plt.figure(figsize=(10, 6))
plt.plot(test_depths, steps_needed, marker='s', color='darkgreen', linewidth=2, markersize=8)
plt.title('Scaling Analysis: Optimization Speed vs. Circuit Depth')
plt.xlabel('Number of Layers (Depth)')
plt.ylabel('Iterations to reach S = 1.95')
plt.grid(True, linestyle='--', alpha=0.6)

# Adding a trendline to check for linear vs non-linear scaling
z = np.polyfit(test_depths, steps_needed, 1)
p = np.poly1d(z)
plt.plot(test_depths, p(test_depths), "r--", alpha=0.5, label='Linear Trend')

plt.legend()
plt.show()

import numpy as py_np

# Calculate the Pearson correlation coefficient matrix
correlation_matrix = py_np.corrcoef(test_depths, steps_needed)

# The correlation coefficient is the off-diagonal element
correlation_coefficient = correlation_matrix[0, 1]

print(f"Correlation Matrix:\n{correlation_matrix}")
print(f"\nPearson Correlation Coefficient (r): {correlation_coefficient:.4f}")

