import numpy as py_np

# Redefine the optimization logic to accept custom initial parameters
def optimize_with_params(init_params, steps=100, lr=0.6):
    params = np.array(init_params, requires_grad=True)
    opt = qml.GradientDescentOptimizer(stepsize=lr)
    energies = []
    for _ in range(steps):
        params, energy = opt.step_and_cost(quantum_project_circuit, params)
        energies.append(float(energy))
    return energies

# Baseline parameters
base_p = [0.15, 0.22, 0.38, 0.41]

# Sensitivity Analysis: 5 different starting points with random noise (+/- 0.2)
num_trials = 5
trial_results = {}

print("--- Starting Parameter Sensitivity Test ---")
for i in range(num_trials):
    # Perturb the baseline
    noise = py_np.random.uniform(-0.2, 0.2, size=4)
    p_start = [base_p[j] + noise[j] for j in range(4)]

    energies = optimize_with_params(p_start)
    trial_results[f"Trial {i+1}"] = energies
    print(f"Trial {i+1} Start: {[round(x, 3) for x in p_start]} -> Final Energy: {energies[-1]:.7f}")

# Plotting Sensitivity
plt.figure(figsize=(12, 6))
for label, data in trial_results.items():
    plt.plot(data, alpha=0.7, label=label)

plt.axhline(y=-3.6661510, color='black', linestyle='--', label='Global Min Target')
plt.title('Sensitivity Analysis: Convergence from Perturbed Initial Parameters')
plt.xlabel('Optimization Step')
plt.ylabel('Energy')
plt.legend()
plt.grid(True, alpha=0.3)
plt.show()

